package com.hrms.inventory;
import com.hrms.shared.*;import com.hrms.identity.Actor;import com.hrms.observability.Audit;import java.time.*;import java.math.BigDecimal;import java.util.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class CalendarController {
 private final Db db;private final Tx tx;private final Actor actor;private final Audit audit;
 public CalendarController(Db db,Tx tx,Actor actor,Audit audit){this.db=db;this.tx=tx;this.actor=actor;this.audit=audit;}
 public static List<LocalDate> nights(LocalDate in,LocalDate out){Problem.require(in!=null&&out!=null&&out.isAfter(in)&&!out.isAfter(in.plusDays(30)),400,"INVALID_STAY");return in.datesUntil(out).toList();}
 public record Inventory(@NotNull LocalDate date,@Min(0) int total,@Min(0) int blocked,@NotNull @Pattern(regexp="OPEN|CLOSED") String saleStatus){}
 public record Rate(@NotNull LocalDate date,@NotNull @DecimalMin("0.01") @Digits(integer=10,fraction=2) BigDecimal price){}
 @GetMapping("/room-types/{id}/calendar") public List<Map<String,Object>> calendar(@PathVariable long id,@RequestParam LocalDate checkIn,@RequestParam LocalDate checkOut){nights(checkIn,checkOut);return db.list("SELECT i.*,r.price FROM room_daily_inventory i JOIN room_types rt ON rt.id=i.room_type_id JOIN hotels h ON h.id=rt.hotel_id LEFT JOIN room_daily_rate r ON r.room_type_id=i.room_type_id AND r.stay_date=i.stay_date WHERE i.room_type_id=? AND i.stay_date>=? AND i.stay_date<? AND rt.status='ACTIVE' AND h.status='OPEN' ORDER BY i.stay_date",id,checkIn,checkOut);}
 private void authorize(long id){var rt=Problem.found(db.one("SELECT hotel_id FROM room_types WHERE id=?",id));actor.hotel(Db.id(rt,"hotel_id"));}
 @PutMapping("/admin/room-types/{id}/inventory") public Map<String,Object> inventory(@PathVariable long id,@Valid @RequestBody Inventory x){authorize(id);return tx.run(()->{db.exec("INSERT IGNORE INTO room_daily_inventory(room_type_id,stay_date,total,available,held,sold,blocked,sale_status) VALUES(?,?,0,0,0,0,0,'CLOSED')",id,x.date());var old=db.one("SELECT * FROM room_daily_inventory WHERE room_type_id=? AND stay_date=? FOR UPDATE",id,x.date());Problem.require(x.total()>=x.blocked()+Db.number(old,"held")+Db.number(old,"sold"),409,"INVENTORY_IN_USE");int available=x.total()-x.blocked()-Db.number(old,"held")-Db.number(old,"sold");db.exec("UPDATE room_daily_inventory SET total=?,blocked=?,available=?,sale_status=?,version=version+1 WHERE room_type_id=? AND stay_date=?",x.total(),x.blocked(),available,x.saleStatus(),id,x.date());db.exec("INSERT INTO inventory_ledger(room_type_id,stay_date,operation,delta_available,delta_held,delta_sold) VALUES(?,?,'ADJUST',?,0,0)",id,x.date(),available-Db.number(old,"available"));audit.log(actor.id(),"INVENTORY_ADJUST",id+":"+x.date());return Map.of("available",available);});}
 @PutMapping("/admin/room-types/{id}/rates") public Map<String,Object> rate(@PathVariable long id,@Valid @RequestBody Rate r){authorize(id);return tx.run(()->{db.exec("INSERT INTO room_daily_rate(room_type_id,stay_date,price) VALUES(?,?,?) ON DUPLICATE KEY UPDATE price=VALUES(price),version=version+1",id,r.date(),r.price());audit.log(actor.id(),"RATE_SET",id+":"+r.date());return Map.of("price",r.price());});}
}
